EXPLAIN QUERY PLAN SELECT p.id FROM poem p WHERE p.publishable=1 AND p.source_hash IS NOT NULL AND EXISTS(SELECT 1 FROM author a WHERE a.id=p.author_id AND a.hidden=0) AND (p.publication_json IS NULL OR p.publication_source_hash IS NULL OR p.publication_source_hash<>p.source_hash) AND (p.rig_status IS NULL OR p.rig_status IN ('retry','complete') OR (p.rig_status='claimed' AND (p.rig_lease_expires_at IS NULL OR p.rig_lease_expires_at<=unixepoch()))) ORDER BY p.id LIMIT 1;
EXPLAIN QUERY PLAN SELECT a.id,(SELECT count(*) FROM poem p WHERE p.author_id=a.id AND p.publishable=1) AS poems FROM author a WHERE a.hidden=0 ORDER BY a.sort_name_arabic,a.id;
